SELECT nct_id, phase_norm, overall_status FROM v_trials WHERE nct_id IN (
  SELECT unnest(nct_ids) FROM v_programs WHERE condition_key='D002292' AND asset_id='pembrolizumab'
) AND phase_norm='Phase 3' ORDER BY overall_status LIMIT 10

SELECT nct_id, phase_norm, phase_rank, overall_status, brief_title FROM v_trials WHERE nct_id IN (
  SELECT unnest(nct_ids) FROM v_programs WHERE condition_key='D002292' AND asset_id='pembrolizumab'
) AND phase_rank>=3 ORDER BY phase_rank DESC LIMIT 15

